    "portfolio.card2.meta": { pt: "Colunex Portugal &middot; Janeiro 2001 a Setembro 2008", en: "Colunex Portugal &middot; January 2001 to September 2008", fr: "Colunex Portugal &middot; janvier 2001 – septembre 2008", es: "Colunex Portugal &middot; enero de 2001 – septiembre de 2008" },
    "portfolio.card2.title": { pt: "Diretora de Marketing", en: "Marketing Director", fr: "Directrice marketing", es: "Directora de marketing" },
    "portfolio.card2.desc": {
      pt: "Direção de marketing e comunicação estratégica na Colunex, marca portuguesa de colchões, camas e almofadas fundada em 1986 em Recarei, Paredes. Execução do plano de comunicação e marketing, organização de eventos, coordenação de lojas e vitrinismo e copywriting, num período de forte crescimento da marca em Portugal que antecedeu a sua expansão para mais de 40 mercados internacionais.",
      en: "Strategic marketing and communication direction at Colunex, a Portuguese mattress, bed and pillow brand founded in 1986 in Recarei, Paredes. Execution of the communication and marketing plan, event organisation, store and window-display coordination and copywriting, during a period of strong brand growth in Portugal that preceded its expansion into more than 40 international markets.",
      fr: "Direction du marketing et de la communication stratégique chez Colunex, marque portugaise de matelas, lits et oreillers fondée en 1986 à Recarei, Paredes. Exécution du plan de communication et de marketing, organisation d'événements, coordination des magasins et de la vitrine, et copywriting, durant une période de forte croissance de la marque au Portugal qui a précédé son expansion vers plus de 40 marchés internationaux.",
      es: "Dirección de marketing y comunicación estratégica en Colunex, marca portuguesa de colchones, camas y almohadas fundada en 1986 en Recarei, Paredes. Ejecución del plan de comunicación y marketing, organización de eventos, coordinación de tiendas y escaparatismo, y copywriting, durante un periodo de fuerte crecimiento de la marca en Portugal que precedió a su expansión a más de 40 mercados internacionales."
    },
    "portfolio.card2.link.case": { pt: "Caso de sucesso", en: "Success story", fr: "Étude de cas", es: "Caso de éxito" },

